import { setResponseHeader } from 'h3'
import { adminFetch } from '~/server/utils/adminDirectusClient'

/**
 * Site check: a read-only picture of how the 100-odd public records are actually described.
 *
 * Nothing here is generated by a model and nothing is written. It counts what is missing, too short,
 * too long or duplicated, and how much changed today, so the person can decide where to spend the
 * assistant's time instead of guessing. The assistant summary is a separate endpoint that only reads
 * this result.
 */
export interface SiteAuditIssue {
  id: string | number
  label: string
  slug: string
  problems: string[]
}

export interface SiteAuditCollection {
  total: number
  missingSeoTitle: number
  missingSeoDescription: number
  shortTitle: number
  longTitle: number
  shortDescription: number
  longDescription: number
  updatedToday: number
  issues: SiteAuditIssue[]
}

export interface SiteAudit {
  generatedAt: string
  collections: Record<'posts' | 'products' | 'categories', SiteAuditCollection>
  media: {
    total: number
    unclassified: number
    withoutAlt: number
  }
}

const TITLE_IDEAL_MIN = 30
const TITLE_IDEAL_MAX = 65
const DESCRIPTION_IDEAL_MIN = 70
const DESCRIPTION_IDEAL_MAX = 165

const today = () => new Date().toISOString().slice(0, 10)

/**
 * 每个集合暴露的时间戳字段不一样，而且有的集合的 `updated_at` 对服务账号不可读。
 * 逐个试候选字段，全部失败就退到不带时间戳的查询（今日更新数为 0，其余统计照常）。
 */
async function fetchRows(
  event: Parameters<typeof adminFetch>[0],
  collection: 'posts' | 'products',
  baseFields: string,
  candidates: readonly string[],
): Promise<Array<Record<string, unknown>>> {
  const filter = collection === 'posts' ? 'filter[status][_eq]=published&' : 'filter[status][_eq]=published&'
  for (const field of candidates) {
    try {
      const res = await adminFetch<{ data: Array<Record<string, unknown>> }>(
        event,
        `/items/${collection}?${filter}fields=${baseFields},${field}&limit=-1`,
      )
      return (res?.data ?? []).map(row => ({ ...row, __updated: row[field] }))
    }
    catch {
      // 这个集合没有这个字段（或不可读）：试下一个。
    }
  }
  const res = await adminFetch<{ data: Array<Record<string, unknown>> }>(
    event,
    `/items/${collection}?${filter}fields=${baseFields}&limit=-1`,
  )
  return res?.data ?? []
}

function isToday(value: unknown): boolean {
  return typeof value === 'string' && value.slice(0, 10) === today()
}

function evaluate(
  rows: Array<{ id: string | number, label: string, slug: string, title: string, description: string, updated: unknown }>,
): SiteAuditCollection {
  const out: SiteAuditCollection = {
    total: rows.length,
    missingSeoTitle: 0,
    missingSeoDescription: 0,
    shortTitle: 0,
    longTitle: 0,
    shortDescription: 0,
    longDescription: 0,
    updatedToday: 0,
    issues: [],
  }
  for (const row of rows) {
    const problems: string[] = []
    const title = row.title.trim()
    const description = row.description.trim()

    if (!title) { out.missingSeoTitle++; problems.push('no search title') }
    else if (title.length < TITLE_IDEAL_MIN) { out.shortTitle++; problems.push(`search title ${title.length} chars (short)`) }
    else if (title.length > TITLE_IDEAL_MAX) { out.longTitle++; problems.push(`search title ${title.length} chars (long)`) }

    if (!description) { out.missingSeoDescription++; problems.push('no search description') }
    else if (description.length < DESCRIPTION_IDEAL_MIN) { out.shortDescription++; problems.push(`description ${description.length} chars (short)`) }
    else if (description.length > DESCRIPTION_IDEAL_MAX) { out.longDescription++; problems.push(`description ${description.length} chars (long)`) }

    if (isToday(row.updated)) out.updatedToday++

    if (problems.length) out.issues.push({ id: row.id, label: row.label, slug: row.slug, problems })
  }
  return out
}

function duplicatesOf(rows: Array<{ title: string }>): number {
  const seen = new Map<string, number>()
  for (const row of rows) {
    const key = row.title.trim().toLowerCase()
    if (!key) continue
    seen.set(key, (seen.get(key) ?? 0) + 1)
  }
  let duplicates = 0
  for (const count of seen.values()) if (count > 1) duplicates += count
  return duplicates
}

export default defineEventHandler(async (event): Promise<SiteAudit> => {
  setResponseHeader(event, 'Cache-Control', 'private, no-store')

  const [postRes, productRes, categoryRes, fileRes] = await Promise.all([
    // 时间戳字段名各集合不同，且 products.updated_at 不可读，所以逐个试，最后的退路是不带时间戳。
    fetchRows(event, 'posts', 'id,slug,title_en,seo_title_en,seo_description_en', ['updated_at', 'date_updated']),
    fetchRows(event, 'products', 'id,slug,name_en,seo_title_en,seo_description_en', ['date_updated', 'updated_at']),
    adminFetch<{ data: Array<Record<string, unknown>> }>(
      event,
      '/items/product_categories?fields=id,slug,name_en,seo_title_en,seo_description_en&limit=-1',
    ),
    adminFetch<{ data: Array<{ id: string, title: string | null, filename_download: string | null, folder: string | null, type: string | null }> }>(
      event,
      '/files?fields=id,title,filename_download,folder,type&limit=-1',
    ),
  ])

  const posts = (postRes ?? []).map(r => ({
    id: r.id as number,
    label: String(r.title_en ?? ''),
    slug: String(r.slug ?? ''),
    title: String(r.seo_title_en ?? ''),
    description: String(r.seo_description_en ?? ''),
    updated: r.__updated,
  }))
  const products = (productRes ?? []).map(r => ({
    id: r.id as number,
    label: String(r.name_en ?? ''),
    slug: String(r.slug ?? ''),
    title: String(r.seo_title_en ?? ''),
    description: String(r.seo_description_en ?? ''),
    updated: r.__updated,
  }))
  const categories = (categoryRes?.data ?? []).map(r => ({
    id: r.id as number,
    label: String(r.name_en ?? ''),
    slug: String(r.slug ?? ''),
    title: String(r.seo_title_en ?? ''),
    description: String(r.seo_description_en ?? ''),
    updated: null,
  }))

  const collections = {
    posts: evaluate(posts),
    products: evaluate(products),
    categories: evaluate(categories),
  }

  const files = fileRes?.data ?? []
  const images = files.filter(f => (f.type ?? '').startsWith('image/'))
  const withoutAlt = images.filter(f => {
    const title = (f.title ?? '').trim()
    if (!title) return true
    const name = (f.filename_download ?? '').trim()
    return Boolean(name) && title.toLowerCase() === name.toLowerCase()
  })

  return {
    generatedAt: new Date().toISOString(),
    collections,
    media: {
      total: images.length,
      unclassified: images.filter(f => !f.folder).length,
      withoutAlt: withoutAlt.length,
    },
    // 重复标题单独列出，因为它不是"某一条的问题"，而是一对记录互相竞争。
    ...(duplicatesOf(posts) + duplicatesOf(products) + duplicatesOf(categories) > 0
      ? { duplicateSeoTitles: duplicatesOf(posts) + duplicatesOf(products) + duplicatesOf(categories) }
      : {}),
  } as SiteAudit
})
